output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Carts should not be taken into one-cell-wide shelf aisles, a layout-invariant bottleneck identified by opposing shelves and narrow free width.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "do_not_enter_single_file_aisle_with_cart",
    "text": "A shopper must not move from a circulation area into a single-file shelf aisle while still holding the cart, regardless of where that aisle is located.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "enter_single_file_aisle_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "single_file_shelf_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enter_single_file_aisle_with_cart"
    }
  },
  {
    "id": "no_cart_movement_inside_single_file_aisle",
    "text": "Even if already inside a single-file shelf aisle, a shopper should not continue moving through it with a cart because the concern is obstruction, not a particular coordinate.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle",
          "MOVE"
        ]
      }
    }
  },
  {
    "id": "no_cart_item_handling_in_single_file_aisle",
    "text": "Items in single-file shelf aisles should be handled without the cart, a relational rule tied to aisle narrowness rather than to the observed item positions.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "park_cart_only_in_open_circulation",
    "text": "When temporarily leaving a cart, the shopper should park it only in open circulation space rather than beside shelves or in a narrow aisle, which generalizes across rearranged layouts.",
    "abstraction": {
      "state_properties": {
        "open_circulation_space": {
          "and": [
            {
              "not": "adjShelf"
            },
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            }
          ]
        }
      },
      "events": {
        "drop_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "drop_cart",
          {
            "not": "open_circulation_space"
          }
        ]
      }
    }
  },
  {
    "id": "recover_temporarily_parked_cart",
    "text": "A shopper who parks a cart to enter a constrained shopping aisle must later recover it, a behavior tied to cart custody rather than any fixed station location.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "drop_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pick_up_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "drop_cart",
      "discharge": "pick_up_cart"
    }
  },
  {
    "id": "return_to_cart_after_cartless_aisle_item",
    "text": "After taking an item while cartless in a single-file shelf aisle, the shopper should return to having the cart before leaving the store, independent of the aisle orientation.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        },
        "cartless_single_file_item_interaction": {
          "and": [
            {
              "not": "hasCart"
            },
            "single_file_shelf_aisle",
            "INTERACT"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartless_single_file_item_interaction",
      "discharge": "hasCart"
    }
  },
  {
    "id": "exit_with_cart",
    "text": "A shopper using the supermarket should leave through the exit with the cart, a role-based rule that does not depend on where the exit cell happens to be.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
